/* Camera preference is separate from story saves. V works in every event week. */
const playerCamera={third:false,distance:3.2,actualDistance:0};
try{playerCamera.third=localStorage.getItem('spare-camera')==='third';}catch{}
const cameraButton=document.createElement('button');toolbar.append(cameraButton);
function setThirdPerson(value){playerCamera.third=!!value;playerCamera.actualDistance=0;try{localStorage.setItem('spare-camera',value?'third':'first');}catch{}cameraButton.textContent=value?'CAMERA · THIRD PERSON (V)':'CAMERA · FIRST PERSON (V)';house.dirty=true;}
cameraButton.onclick=()=>setThirdPerson(!playerCamera.third);setThirdPerson(playerCamera.third);
document.addEventListener('keydown',event=>{if(event.code==='KeyV'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName||'')&&!event.repeat){event.preventDefault();setThirdPerson(!playerCamera.third);}});
function createPlayerAvatar(e){const T=THREE,rig=createCitizenRig({name:'player-avatar',coat:'#53625b',trousers:'#353d43',hair:'#352f2d'});e.scene.add(rig.root);const bag=engineBox(rig.torso,.235,.86,-.08,.14,.25,.2,'#68503c');bag.rotation.z=-.08;for(const side of [-1,1]){const strap=engineBox(rig.torso,side*.2,1.05,-.13,.027,.28,.025,'#3a332d');strap.rotation.z=side*.13;}return {...rig,ray:new T.Raycaster(),headPoint:new T.Vector3(),direction:new T.Vector3(),desired:new T.Vector3(),sample:new T.Vector3(),lastX:house.x,lastZ:house.z,lastTime:s.worldSeconds||0,stride:0};}
function applyPlayerCamera(e){if(!e.playerAvatar)e.playerAvatar=createPlayerAvatar(e);const p=e.playerAvatar,feet=house.jumpHeight||0; p.root.visible=playerCamera.third;p.root.position.set(house.x,feet,-house.z);p.root.rotation.y=Math.PI-house.a;
 const time=s.worldSeconds||0,dt=paused()?0:Math.min(.1,Math.max(0,time-p.lastTime)),travel=Math.hypot(house.x-p.lastX,house.z-p.lastZ),speed=dt>0?Math.min(5,travel/dt):0,grounded=feet<=supportAt(house.x,house.z)+.15,blend=1-Math.exp(-dt*12);p.lastX=house.x;p.lastZ=house.z;p.lastTime=time;p.stride+=(Math.min(1,speed/2.2)-p.stride)*blend;
 p.action.setEffectiveWeight(grounded?p.stride:0);p.action.timeScale=house.sprinting?1.65:1;p.mixer.update(dt);p.torso.position.y=grounded?Math.sin(time*1.7)*.007:0;p.torso.rotation.x=grounded?(house.sprinting?-.08:0):-.05;p.head.rotation.x=-house.pitch*.35;
 for(const limb of p.limbs){if(!grounded){limb.hip.rotation.x=-.28;limb.knee.rotation.x=.58;limb.arm.rotation.x=-.25;limb.elbow.rotation.x=-.35;}else{limb.hip.rotation.x*=p.stride;limb.knee.rotation.x*=p.stride;limb.arm.rotation.x*=p.stride;limb.elbow.rotation.x=-.12-(house.sprinting?.38:.07)*p.stride;}}
 if(!playerCamera.third){playerCamera.actualDistance=0;return;}
 e.camera.updateMatrixWorld(true);p.headPoint.set(house.x,1.5+feet,-house.z);p.direction.set(0,0,1).applyQuaternion(e.camera.quaternion);p.desired.copy(p.headPoint).addScaledVector(p.direction,playerCamera.distance);p.desired.y+=.35;p.desired.x+=Math.cos(house.a)*.4;p.desired.z+=Math.sin(house.a)*.4;
 p.direction.copy(p.desired).sub(p.headPoint);let length=p.direction.length();p.direction.normalize();e.world.updateMatrixWorld(true);p.ray.set(p.headPoint,p.direction);p.ray.near=.03;p.ray.far=length+.15;const hit=p.ray.intersectObjects(e.world.children,true).find(h=>h.object.isMesh&&h.distance>.03);let distance=hit?Math.max(0,hit.distance-.22):length;
 // Probe a small camera volume as well as the centre ray to keep corners out of the lens.
 for(const dx of [-.14,.14]){p.sample.copy(p.headPoint);p.sample.x+=Math.cos(house.a)*dx;p.sample.z+=Math.sin(house.a)*dx;p.ray.set(p.sample,p.direction);const h=p.ray.intersectObjects(e.world.children,true)[0];if(h)distance=Math.min(distance,Math.max(0,h.distance-.22));}
 playerCamera.actualDistance=distance;e.camera.position.copy(p.headPoint).addScaledVector(p.direction,distance);p.root.visible=distance>.65;e.camera.updateMatrixWorld(true);
}
const playerPreviousView=view;view=function(point){if(!playerCamera.third||!advancedEngine||advancedEngine.failed)return playerPreviousView(point);const v=new THREE.Vector3(point[0],point[1],-point[2]).applyMatrix4(advancedEngine.camera.matrixWorldInverse);return [v.x,v.y,-v.z];};

const playerPreviousVisibility=visibleTo;visibleTo=function(target){if(!playerPreviousVisibility(target))return false;if(!playerCamera.third||!advancedEngine)return true;const c=advancedEngine.camera.position,start=[c.x,c.y,-c.z],distance=Math.hypot(target.p[0]-start[0],target.p[1]-start[1],target.p[2]-start[2]);for(let d=.1;d<distance-.35;d+=.1){const t=d/distance,x=start[0]+(target.p[0]-start[0])*t,y=start[1]+(target.p[1]-start[1])*t,z=start[2]+(target.p[2]-start[2])*t;if(house.solids.some(b=>y>b.y&&y<b.y+b.h&&Math.abs(x-b.x)<b.w/2&&Math.abs(z-b.z)<b.d/2))return false;}return true;};
